"""Binary echo protocol with CRC32 integrity checking over TCP.

Frame layout (all big-endian):
    magic   u16  0xBEEF
    seq     u32  sequence number
    length  u16  payload length
    payload      <length> bytes
    crc     u32  zlib.crc32 over seq + length + payload

Server behaviour per incoming frame:
    - good CRC  -> ACK frame, payload = original payload reversed, same seq
    - bad CRC   -> NAK frame, payload = b'CRC', same seq
    - bad magic -> connection is closed immediately
"""

import socket
import struct
import threading
import zlib

MAGIC = 0xBEEF
HEADER_MAGIC = struct.pack("!H", MAGIC)


def build_frame(seq, payload):
    """Serialize one protocol frame."""
    body = struct.pack("!IH", seq, len(payload)) + payload
    crc = zlib.crc32(body) & 0xFFFFFFFF
    return HEADER_MAGIC + body + struct.pack("!I", crc)


def _expected_crc(seq, length, payload):
    return zlib.crc32(struct.pack("!IH", seq, length) + payload) & 0xFFFFFFFF


def recv_exact(sock, n):
    """Read exactly n bytes, looping over recv() to survive short reads."""
    buf = bytearray()
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk:
            raise ConnectionError("connection closed mid-frame")
        buf.extend(chunk)
    return bytes(buf)


def handle_connection(conn):
    """Serve one client until error, EOF, or bad magic."""
    try:
        while True:
            # Bad magic: drop the connection.
            if recv_exact(conn, 2) != HEADER_MAGIC:
                return
            seq, length = struct.unpack("!IH", recv_exact(conn, 6))
            payload = recv_exact(conn, length)
            (crc,) = struct.unpack("!I", recv_exact(conn, 4))

            if crc == _expected_crc(seq, length, payload):
                reply = build_frame(seq, payload[::-1])          # ACK
            else:
                reply = build_frame(seq, b"CRC")                 # NAK
            conn.sendall(reply)
    except (ConnectionError, OSError):
        pass
    finally:
        try:
            conn.close()
        except OSError:
            pass


def serve(sock_srv):
    """Accept loop; one daemon-ish thread per connection is spawned by caller."""
    try:
        while True:
            conn, _ = sock_srv.accept()
            threading.Thread(
                target=handle_connection, args=(conn,), daemon=True
            ).start()
    except OSError:
        pass


class Server:
    """TCP server bound to localhost; use port=0 for an ephemeral port."""

    def __init__(self, host="127.0.0.1", port=0):
        self.sock_srv = socket.create_server((host, port), backlog=16)
        self.host, self.port = self.sock_srv.getsockname()[:2]
        self._thread = threading.Thread(target=serve, args=(self.sock_srv,), daemon=True)
        self._thread.start()

    def close(self):
        self.sock_srv.close()


class EchoClient:
    """Client that speaks the framed protocol."""

    def __init__(self, host="127.0.0.1", port=0, timeout=4.0):
        self.sock = socket.create_connection((host, port), timeout=timeout)

    def send_frame(self, seq, payload):
        self.sock.sendall(build_frame(seq, payload))

    def send_raw(self, data):
        """Send arbitrary bytes (for corruption / split-boundary tests)."""
        self.sock.sendall(data)

    def recv_frame(self):
        """Receive one frame. Returns (seq, payload), or None if the peer
        closed the connection (recv returned b'')."""
        try:
            if recv_exact(self.sock, 2) != HEADER_MAGIC:
                return None  # shouldn't happen against our own server
            seq, length = struct.unpack("!IH", recv_exact(self.sock, 6))
            payload = recv_exact(self.sock, length)
            recv_exact(self.sock, 4)  # CRC (already trusted from our server)
        except ConnectionError:
            return None
        return seq, payload

    def close(self):
        try:
            self.sock.close()
        except OSError:
            pass


def main(host="127.0.0.1", port=9999):
    Server(host, port)
    print(f"checked-echo server listening on {host}:{port}")
    threading.Event().wait()  # run forever


if __name__ == "__main__":
    main()

